--   The plan is nerdery/flights/repair.steps.json; its digest is sha256:31a627482aa3cc6d285c485b6d22707f18283e69b10b0654454bc8750cbdecc4.
-- RUN repair-1-estate FIRST. WHERE: sfx-identity. Run the whole file in one session (a few seconds).
-- GUARDS: the owner principal is active; the plan writer has its four parameters; the agent's current plan is the fast
-- path's or this one. RESULT SETS: base; plans (matches_reviewed_file 1).
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @p uniqueidentifier='565de6d4-ebcd-408b-9359-04d21dc62183';
DECLARE @owner int=(SELECT COUNT(*) FROM [identity].principal WHERE principal_id=@p AND active=1),
 @params int=(SELECT COUNT(*) FROM sys.parameters WHERE object_id=OBJECT_ID(N'evidence.upsert_flight_plan') AND name IN (N'@principal_id',N'@agent_id',N'@objective',N'@steps_json'));
DECLARE @current binary(32)=(SELECT plan_digest FROM evidence.flight_plan WHERE principal_id=@p AND agent_id=N'claude-code-opus-5-5-nerdery-slice');
SELECT N'base' AS result_set,@owner AS owner_principal_active,@params AS plan_writer_parameters,N'sha256:'+LOWER(CONVERT(varchar(64),@current,2)) AS current_plan;
IF @owner<>1 OR @params<>4 OR @current IS NULL OR @current NOT IN (CONVERT(binary(32),'8ffc4ac2cab7fec7524ebd222f6696070f94d6c6f11e6668715c24e1489bcd1f',2),CONVERT(binary(32),'31a627482aa3cc6d285c485b6d22707f18283e69b10b0654454bc8750cbdecc4',2))
BEGIN
 RAISERROR(N'REPAIR2_BASE: the owner principal, the plan writer or the agent''s current plan is not as reviewed; nothing is changed.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
